import ctypes, json, sys, random
from pathlib import Path
sys.path.insert(0, '/workspace/vendor'); sys.path.insert(0, '/workspace/submission'); sys.path.insert(0, '/workspace')
import ctypes as c
c.CDLL('/workspace/vendor/system-libs/libz.so.1', mode=c.CTLD_GLOBAL)
import dev.gen as gen, dev.reference2 as ref2
from netnomos.finite import compile_job

n = int(sys.argv[1]); seed0 = int(sys.argv[2]); mode = sys.argv[3] if len(sys.argv) > 3 else 'cells'
bad = 0
for it in range(n):
    rng = random.Random(seed0 + it)
    if mode == 'cells':
        job = gen.make_job(rng, max_universe=20000, max_pred=12, max_train=60, max_width=4,
                           max_queries=5, max_nf=4, domain_size=2, value_hi=40)
    elif mode == 'wide':
        job = gen.make_job(rng, max_universe=30000, max_pred=10, max_train=80, max_width=3,
                           max_queries=5, max_nf=2, domain_size=200, value_hi=900)
    else:
        job = gen.make_job(rng, max_universe=8000, max_pred=14, max_train=50, max_width=4, max_queries=5)
    got = compile_job(job)
    exp = ref2.compile_job(job)
    if got != exp:
        bad += 1
        print('MISMATCH', it, mode)
        print(json.dumps(job)[:4000])
        for k in ('rules', 'active', 'answers'):
            if got[k] != exp[k]:
                print('key', k)
                print('GOT', json.dumps(got[k])[:1500])
                print('EXP', json.dumps(exp[k])[:1500])
        if bad >= 2:
            break
    else:
        # approve a subset of discovered rules and re-check decoding
        if exp['rules']:
            picks = rng.sample(exp['rules'], rng.randint(1, len(exp['rules'])))
            job['approved'] = [list(r['clause']) for r in picks]
            if compile_job(job) != ref2.compile_job(job):
                bad += 1
                print('MISMATCH pass2', it, mode)
                print(json.dumps(job)[:4000])
                break
print('done', n, 'bad', bad)
